// Every PayPal call the app makes goes through here.
//  - Orders use @paypal/paypal-server-sdk (generated by APIMatic).
//  - Payouts, Balances, Transaction Search and Webhooks are not covered by that SDK, so they use
//    plain REST with the same client-credentials app and a cached OAuth token.
// Each call is logged (method, path, status, PayPal-Debug-Id, feature) for the Under the hood drawer,
// and every POST carries a PayPal-Request-Id so a retry can never move money twice.

import { randomUUID } from 'node:crypto';
import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  OrdersController,
  type OrderRequest,
} from '@paypal/paypal-server-sdk';
import { ctx, logCall } from './context';
import { readFixture, recordFixture, recording } from './fixtures';

const BASE = 'https://api-m.sandbox.paypal.com';

function credentials() {
  const id = process.env.PAYPAL_CLIENT_ID;
  const secret = process.env.PAYPAL_CLIENT_SECRET;
  if (!id || !secret) throw new Error('PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET are not set.');
  if ((process.env.PAYPAL_ENVIRONMENT ?? 'sandbox') !== 'sandbox') throw new Error('Payday only runs against the PayPal sandbox.');
  return { id, secret };
}

let token: { value: string; expires: number } | null = null;

export async function accessToken(): Promise<string> {
  if (token && token.expires > Date.now() + 60_000) return token.value;
  const { id, secret } = credentials();
  const started = Date.now();
  const res = await fetch(`${BASE}/v1/oauth2/token`, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${Buffer.from(`${id}:${secret}`).toString('base64')}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: 'grant_type=client_credentials',
  });
  logCall({ method: 'POST', path: '/v1/oauth2/token', status: res.status, debugId: res.headers.get('paypal-debug-id') ?? '', ms: Date.now() - started, via: 'REST' });
  if (!res.ok) throw new Error(`PayPal OAuth failed (${res.status})`);
  const json = (await res.json()) as { access_token: string; expires_in: number };
  token = { value: json.access_token, expires: Date.now() + json.expires_in * 1000 };
  return token.value;
}

export class PayPalError extends Error {
  constructor(public status: number, public debugId: string, public body: unknown, message: string) {
    super(message);
  }
}

type Recorded = { status: number; debugId: string; body: unknown };

/** Replaces ids in a path so that one recorded response answers for any id: /v1/payments/payouts/{id}. */
export const pattern = (path: string) =>
  path
    .split('?')[0]
    .split('/')
    .map((seg) => (/^[A-Z0-9]{10,}$/.test(seg) || /^WH-/.test(seg) ? '{id}' : seg))
    .join('/');

export type CallOptions = { body?: unknown; requestId?: string; fixtureKey?: string; via?: string; okStatuses?: number[] };

export async function paypal<T>(method: 'GET' | 'POST' | 'DELETE' | 'PATCH', path: string, opts: CallOptions = {}): Promise<T> {
  const key = opts.fixtureKey ?? `${method} ${pattern(path)}`;
  const started = Date.now();

  if (ctx().mode === 'replay') {
    const hit = readFixture<Recorded>('paypal', key);
    if (!hit) throw new Error(`Replay has no recording for ${key}. Switch to Live to call the sandbox.`);
    await new Promise((r) => setTimeout(r, 350));
    logCall({ method, path: path.split('?')[0], status: hit.status, debugId: hit.debugId, ms: Date.now() - started, via: opts.via ?? 'REST' });
    return hit.body as T;
  }

  let lastError: unknown;
  for (let attempt = 0; attempt < 3; attempt++) {
    const res = await fetch(`${BASE}${path}`, {
      method,
      headers: {
        Authorization: `Bearer ${await accessToken()}`,
        'Content-Type': 'application/json',
        ...(method === 'POST' && { 'PayPal-Request-Id': opts.requestId ?? randomUUID() }),
      },
      body: opts.body === undefined ? undefined : JSON.stringify(opts.body),
      cache: 'no-store',
    });
    const debugId = res.headers.get('paypal-debug-id') ?? '';
    logCall({ method, path: path.split('?')[0], status: res.status, debugId, ms: Date.now() - started, via: opts.via ?? 'REST' });
    const text = await res.text();
    const body = text ? safeJson(text) : null;
    if (res.ok || opts.okStatuses?.includes(res.status)) {
      if (recording()) await recordFixture('paypal', key, { status: res.status, debugId, body });
      return body as T;
    }
    if (res.status === 401) token = null;
    const message = (body as { message?: string; name?: string } | null)?.message ?? `PayPal ${method} ${path} failed`;
    lastError = new PayPalError(res.status, debugId, body, `${message} (HTTP ${res.status}, debug id ${debugId})`);
    if (![401, 429, 500, 502, 503, 504].includes(res.status)) break;
    await new Promise((r) => setTimeout(r, 600 * (attempt + 1)));
  }
  throw lastError;
}

const safeJson = (text: string) => {
  try {
    return JSON.parse(text);
  } catch {
    return text;
  }
};

// --- Payouts -------------------------------------------------------------------------------

export type PayoutItemInput = { senderItemId: string; email: string; amount: number; note: string };

export type PayPalPayoutItem = {
  payout_item_id: string;
  transaction_id?: string;
  transaction_status: string;
  payout_item_fee?: { value: string };
  payout_batch_id: string;
  payout_item: { receiver: string; amount: { value: string }; sender_item_id: string };
  time_processed?: string;
  errors?: { name?: string; message?: string };
};

export type PayPalBatch = {
  batch_header: {
    payout_batch_id: string;
    batch_status: string;
    time_created?: string;
    time_completed?: string;
    amount?: { value: string };
    fees?: { value: string };
  };
  items?: PayPalPayoutItem[];
};

/** POST /v1/payments/payouts. `senderBatchId` doubles as the PayPal-Request-Id, so the same batch is never created twice. */
export function createPayoutBatch(senderBatchId: string, items: PayoutItemInput[]) {
  return paypal<PayPalBatch>('POST', '/v1/payments/payouts', {
    requestId: senderBatchId,
    body: {
      sender_batch_header: {
        sender_batch_id: senderBatchId,
        email_subject: 'TidyNest paid you for today\'s job',
        email_message: 'Your job was verified and paid the same day through Payday.',
      },
      items: items.map((i) => ({
        recipient_type: 'EMAIL',
        receiver: i.email,
        amount: { value: i.amount.toFixed(2), currency: 'USD' },
        note: i.note,
        sender_item_id: i.senderItemId,
      })),
    },
  });
}

/** GET /v1/payments/payouts/{payout_batch_id} */
export const getPayoutBatch = (batchId: string) => paypal<PayPalBatch>('GET', `/v1/payments/payouts/${batchId}?page_size=100&total_required=true`);

/** GET /v1/payments/payouts-item/{payout_item_id} */
export const getPayoutItem = (itemId: string) => paypal<PayPalPayoutItem>('GET', `/v1/payments/payouts-item/${itemId}`);

/** POST /v1/payments/payouts-item/{payout_item_id}/cancel. Only works while the item is UNCLAIMED. */
export const cancelPayoutItem = (itemId: string) =>
  paypal<PayPalPayoutItem>('POST', `/v1/payments/payouts-item/${itemId}/cancel`, { requestId: `cancel-${itemId}` });

// --- Reporting -----------------------------------------------------------------------------

export type Balances = {
  balances: { currency: string; total_balance: { value: string }; available_balance: { value: string }; withheld_balance?: { value: string } }[];
  as_of_time?: string;
  last_refresh_time?: string;
};

/** GET /v1/reporting/balances */
export const getBalances = () => paypal<Balances>('GET', '/v1/reporting/balances?currency_code=USD');

export type TransactionSearch = {
  transaction_details?: {
    transaction_info: {
      transaction_id: string;
      transaction_event_code: string;
      transaction_initiation_date: string;
      transaction_amount: { value: string; currency_code: string };
      fee_amount?: { value: string };
      transaction_status: string;
      transaction_subject?: string;
      transaction_note?: string;
    };
    payer_info?: { email_address?: string };
  }[];
  total_items?: number;
  last_refreshed_datetime?: string;
};

const noMillis = (d: Date) => d.toISOString().replace(/\.\d{3}Z$/, 'Z');

/** GET /v1/reporting/transactions. Lags the ledger by up to three hours; at most 31 days per request. */
export const searchTransactions = (start: Date, end: Date) =>
  paypal<TransactionSearch>(
    'GET',
    `/v1/reporting/transactions?start_date=${encodeURIComponent(noMillis(start))}&end_date=${encodeURIComponent(noMillis(end))}&fields=transaction_info,payer_info&page_size=200`,
  );

// --- Webhooks ------------------------------------------------------------------------------

export const WEBHOOK_EVENTS = [
  'PAYMENT.PAYOUTSBATCH.SUCCESS',
  'PAYMENT.PAYOUTSBATCH.DENIED',
  'PAYMENT.PAYOUTS-ITEM.SUCCEEDED',
  'PAYMENT.PAYOUTS-ITEM.UNCLAIMED',
  'PAYMENT.PAYOUTS-ITEM.FAILED',
  'PAYMENT.PAYOUTS-ITEM.CANCELED',
  'PAYMENT.PAYOUTS-ITEM.RETURNED',
  'CHECKOUT.ORDER.COMPLETED',
] as const;

type Webhook = { id: string; url: string; event_types: { name: string }[] };

/** GET /v1/notifications/webhooks */
export const listWebhooks = () => paypal<{ webhooks: Webhook[] }>('GET', '/v1/notifications/webhooks');

/** POST /v1/notifications/webhooks */
export const createWebhook = (url: string) =>
  paypal<Webhook>('POST', '/v1/notifications/webhooks', { body: { url, event_types: WEBHOOK_EVENTS.map((name) => ({ name })) } });

/** DELETE /v1/notifications/webhooks/{id} */
export const deleteWebhook = (id: string) => paypal<null>('DELETE', `/v1/notifications/webhooks/${id}`);

/** POST /v1/notifications/verify-webhook-signature */
export async function verifyWebhookSignature(headers: Headers, rawBody: string, webhookId: string): Promise<boolean> {
  const h = (name: string) => headers.get(name) ?? '';
  const result = await paypal<{ verification_status: string }>('POST', '/v1/notifications/verify-webhook-signature', {
    body: {
      auth_algo: h('paypal-auth-algo'),
      cert_url: h('paypal-cert-url'),
      transmission_id: h('paypal-transmission-id'),
      transmission_sig: h('paypal-transmission-sig'),
      transmission_time: h('paypal-transmission-time'),
      webhook_id: webhookId,
      webhook_event: JSON.parse(rawBody),
    },
  });
  return result.verification_status === 'SUCCESS';
}

// --- Orders (Server SDK) -------------------------------------------------------------------

let sdk: Client | null = null;
function sdkClient() {
  if (sdk) return sdk;
  const { id, secret } = credentials();
  sdk = new Client({
    clientCredentialsAuthCredentials: { oAuthClientId: id, oAuthClientSecret: secret },
    environment: Environment.Sandbox,
    timeout: 30_000,
  });
  return sdk;
}

export type CapturedOrder = { id: string; status: string; amount: number; fee: number; captureId?: string };

/**
 * A customer's payment into TidyNest: POST /v2/checkout/orders through the Server SDK, paid with a
 * sandbox test card as the payment source, so the order is created and captured in one call and
 * the seed needs no browser approval.
 */
export async function createCapturedOrder(referenceId: string, amount: number, description: string): Promise<CapturedOrder> {
  const key = 'POST /v2/checkout/orders';
  const started = Date.now();
  if (ctx().mode === 'replay') {
    const hit = readFixture<Recorded>('paypal', key);
    if (!hit) throw new Error(`Replay has no recording for ${key}.`);
    logCall({ method: 'POST', path: '/v2/checkout/orders', status: hit.status, debugId: hit.debugId, ms: 300, via: 'Server SDK' });
    return hit.body as CapturedOrder;
  }
  const body: OrderRequest = {
    intent: CheckoutPaymentIntent.Capture,
    purchaseUnits: [{ referenceId, description, amount: { currencyCode: 'USD', value: amount.toFixed(2) } }],
    paymentSource: {
      card: {
        name: 'TidyNest Customer',
        number: '4111111111111111', // PayPal sandbox test card
        expiry: '2030-12',
        securityCode: '123',
        billingAddress: { addressLine1: '1 Main St', adminArea2: 'San Jose', adminArea1: 'CA', postalCode: '95131', countryCode: 'US' },
      },
    },
  };
  try {
    const res = await new OrdersController(sdkClient()).createOrder({ body, paypalRequestId: `order-${referenceId}`, prefer: 'return=representation' });
    const debugId = String((res.headers as Record<string, string>)['paypal-debug-id'] ?? '');
    logCall({ method: 'POST', path: '/v2/checkout/orders', status: res.statusCode, debugId, ms: Date.now() - started, via: 'Server SDK' });
    const capture = res.result.purchaseUnits?.[0]?.payments?.captures?.[0];
    const out: CapturedOrder = {
      id: res.result.id ?? '',
      status: res.result.status ?? 'UNKNOWN',
      amount: Number(capture?.amount?.value ?? amount),
      fee: Number(capture?.sellerReceivableBreakdown?.paypalFee?.value ?? 0),
      captureId: capture?.id,
    };
    if (recording()) await recordFixture('paypal', key, { status: res.statusCode, debugId, body: out });
    return out;
  } catch (e) {
    if (e instanceof ApiError) {
      const debugId = String((e.headers as Record<string, string>)?.['paypal-debug-id'] ?? '');
      logCall({ method: 'POST', path: '/v2/checkout/orders', status: e.statusCode, debugId, ms: Date.now() - started, via: 'Server SDK' });
      throw new PayPalError(e.statusCode, debugId, e.result, `Order failed (HTTP ${e.statusCode}, debug id ${debugId})`);
    }
    throw e;
  }
}

/** GET /v2/checkout/orders/{id} through the Server SDK. */
export async function getOrder(orderId: string) {
  const started = Date.now();
  const res = await new OrdersController(sdkClient()).getOrder({ id: orderId });
  logCall({
    method: 'GET', path: `/v2/checkout/orders/${orderId}`, status: res.statusCode,
    debugId: String((res.headers as Record<string, string>)['paypal-debug-id'] ?? ''), ms: Date.now() - started, via: 'Server SDK',
  });
  return res.result;
}
